using System;using System.IO;using System.Linq;using System.Text;using System.Text.RegularExpressions;using System.Collections.Generic;
namespace ExtremeLand {
 public static class Publisher {
  public static Pack Prepare(string source,string output,string repo,string version){if(!Engine.Repo(repo)||!Regex.IsMatch(version??"",@"^[A-Za-z0-9][A-Za-z0-9_.-]{0,60}$"))throw new Exception("Indica usuario/repositorio y una versión válida.");string mods=Path.Combine(source,"mods");if(!Directory.Exists(mods))throw new Exception("Selecciona el perfil que contiene mods.");Directory.CreateDirectory(output);var pack=new Pack{version=version,notes="ExtremeLand · Temporada 1"};foreach(var src in Directory.GetFiles(mods,"*.jar")){string name=Path.GetFileName(src);if((File.GetAttributes(src)&FileAttributes.ReparsePoint)!=0)throw new IOException("No se publican archivos enlazados.");string target=Path.Combine(output,name);if(!String.Equals(Path.GetFullPath(src),Path.GetFullPath(target),StringComparison.OrdinalIgnoreCase))File.Copy(src,target,true);if(Engine.Hash(src)!=Engine.Hash(target))throw new IOException("Un mod cambió mientras se preparaba la publicación. Cierra el juego y vuelve a preparar el paquete.");pack.files.Add(new PackFile{path="mods/"+name,url="https://github.com/"+repo+"/releases/download/pack-"+version+"/"+Uri.EscapeDataString(name),sha256=Engine.Hash(src),size=new FileInfo(src).Length});}if(pack.files.Count==0)throw new Exception("El perfil no contiene mods.");Json.Write(Path.Combine(output,"channel.json"),pack);return pack;}
  public static Config Embedded(string exe){using(var f=File.OpenRead(exe)){if(f.Length<12)return new Config();f.Seek(-12,SeekOrigin.End);byte[] tail=new byte[12];f.Read(tail,0,12);int len=BitConverter.ToInt32(tail,0);if(Encoding.ASCII.GetString(tail,4,8)!="ELCFG001"||len<1||len>65536||len>f.Length-12)return new Config();f.Seek(-12-len,SeekOrigin.End);byte[] b=new byte[len];f.Read(b,0,len);return Json.S.Deserialize<Config>(Encoding.UTF8.GetString(b));}}
  public static void Export(string source,string target,Config config){if(String.Equals(Path.GetFullPath(source),Path.GetFullPath(target),StringComparison.OrdinalIgnoreCase))throw new IOException("Guarda una copia para compartir, no encima del launcher abierto.");long length=new FileInfo(source).Length;using(var f=File.OpenRead(source)){if(length>12){f.Seek(-12,SeekOrigin.End);byte[] t=new byte[12];f.Read(t,0,12);int n=BitConverter.ToInt32(t,0);if(Encoding.ASCII.GetString(t,4,8)=="ELCFG001"&&n>0&&n<=65536&&n<=length-12)length-=12+n;}f.Position=0;Directory.CreateDirectory(Path.GetDirectoryName(target));using(var dest=File.Create(target)){byte[] buffer=new byte[131072];long left=length;while(left>0){int n=f.Read(buffer,0,(int)Math.Min(buffer.Length,left));if(n<=0)throw new EndOfStreamException();dest.Write(buffer,0,n);left-=n;}byte[] data=Encoding.UTF8.GetBytes(Json.S.Serialize(config));dest.Write(data,0,data.Length);byte[] size=BitConverter.GetBytes(data.Length);dest.Write(size,0,4);data=Encoding.ASCII.GetBytes("ELCFG001");dest.Write(data,0,data.Length);}}}
 }
}
